func liveCallerDeclarations() []check.CallerReadDeclaration {
	var out []check.CallerReadDeclaration
	for rpc, ids := range callerDeclaredConsumers {
		for _, id := range ids {
			site := callerDeclaredSites[id]
			out = append(out, check.CallerReadDeclaration{RPC: rpc, Producer: site.Producer, Site: site.Site, Kind: site.Kind, Reason: site.Reason})
		}
	}
	return out
}
